new_db='''    public long unresolvedConflictCount(){return count("sync_conflicts",null,null);}\n    public List<Row> recentSyncConflicts(int limit){return rows("SELECT c.*,q.operation AS pending_operation,q.changed_at AS local_changed_at,m.last_synced_at FROM sync_conflicts c LEFT JOIN sync_queue q ON q.entity_type=c.entity_type AND q.entity_id=c.entity_id LEFT JOIN sync_metadata m ON m.entity_type=c.entity_type AND m.entity_id=c.entity_id ORDER BY c.detected_at DESC,c.id DESC LIMIT "+Math.max(1,Math.min(50,limit)),null);}\n    public List<Row> pendingSyncDiagnosticRows(int limit){return rows("SELECT q.*,m.remote_uuid,m.last_synced_at FROM sync_queue q LEFT JOIN sync_metadata m ON m.entity_type=q.entity_type AND m.entity_id=q.entity_id WHERE q.entity_type IN ('customer','site','customer_site','asset','technician','job','job_photo','maintenance_log','job_signature') ORDER BY q.changed_at DESC,q.id DESC LIMIT "+Math.max(1,Math.min(100,limit)),null);}\n    public Row pendingSyncForEntity(String type,long localId){return one("SELECT q.*,m.remote_uuid,m.last_synced_at FROM sync_queue q LEFT JOIN sync_metadata m ON m.entity_type=q.entity_type AND m.entity_id=q.entity_id WHERE q.entity_type=? AND q.entity_id=? LIMIT 1",new String[]{type,String.valueOf(localId)});}\n    public String syncEntityLabel(String type,long localId){\n        if(localId<=0)return type+" #"+localId;Row r;\n        if("customer".equals(type)){r=getCustomer(localId);return r.id()>0?r.s("name"):"Customer #"+localId;}\n        if("site".equals(type)||"customer_site".equals(type)){r=getSite(localId);return r.id()>0?("Site · "+r.s("name")):"Site #"+localId;}\n        if("asset".equals(type)){r=getAsset(localId);return r.id()>0?((r.s("tag").isEmpty()?"Asset":r.s("tag"))+" · "+r.s("name")):"Asset #"+localId;}\n        if("technician".equals(type)){r=getTechnician(localId);return r.id()>0?r.s("name"):"Technician #"+localId;}\n        if("job".equals(type)||"job_signature".equals(type)){r=one("SELECT report_no,title FROM jobs WHERE id=?",new String[]{String.valueOf(localId)});return r.id()>0?(r.s("report_no")+" · "+r.s("title")):"Job #"+localId;}\n        if("job_photo".equals(type)){r=one("SELECT j.report_no,j.title FROM job_photos p JOIN jobs j ON j.id=p.job_id WHERE p.id=?",new String[]{String.valueOf(localId)});return r.s("report_no").isEmpty()?"Job photo #"+localId:(r.s("report_no")+" · photo");}\n        if("maintenance_log".equals(type)){r=one("SELECT a.tag,a.name FROM maintenance_logs l JOIN assets a ON a.id=l.asset_id WHERE l.id=?",new String[]{String.valueOf(localId)});return r.s("name").isEmpty()?"Maintenance #"+localId:((r.s("tag").isEmpty()?"Asset":r.s("tag"))+" · maintenance");}\n        return type+" #"+localId;\n    }\n    public void recordSyncConflict(String type,long localId,String remoteUuid,String reason){if(localId<=0)return;ContentValues v=new ContentValues();v.put("entity_type",type);v.put("entity_id",localId);v.put("remote_uuid",remoteUuid==null?"":remoteUuid);v.put("reason",reason==null?"Cloud change deferred":reason);v.put("detected_at",now());getWritableDatabase().insertWithOnConflict("sync_conflicts",null,v,SQLiteDatabase.CONFLICT_REPLACE);}\n    public void resolveSyncConflict(String type,long localId){getWritableDatabase().delete("sync_conflicts","entity_type=? AND entity_id=?",new String[]{type,String.valueOf(localId)});}\n    public void discardPendingEntitySync(String type,long localId){getWritableDatabase().delete("sync_queue","entity_type=? AND entity_id=?",new String[]{type,String.valueOf(localId)});resolveSyncConflict(type,localId);}\n    public boolean forceApplyRemoteDeletion(String type,long localId,String remoteUuid){if(localId<=0)return false;String table=localTableForType(type);if(table.isEmpty())return false;SQLiteDatabase d=getWritableDatabase();if("customer".equals(type))rehomeSharedSitesBeforeCustomerDelete(localId,false);d.delete(table,"id=?",new String[]{String.valueOf(localId)});markDeletionSynced(type,localId,remoteUuid);cleanupOrphanSyncState();return true;}\n'''
replace_once(DB,old_db,new_db)

insert_cloud='''    public JSONObject cloudConflictSnapshot(String workspaceId,String type,String remoteUuid)throws Exception{\n        if(!backendConfigured())throw new Exception("Supabase backend is not configured");if(!signedIn())throw new Exception("Please sign in first");String wid=workspaceId==null?"":workspaceId.trim(),rid=remoteUuid==null?"":remoteUuid.trim();if(wid.isEmpty()||rid.isEmpty())throw new Exception("Conflict is missing its cloud reference");\n        WorkspaceMembership membership=refreshWorkspaceAccess(wid);if(membership==null)throw new Exception("Workspace access is disabled or removed");JSONArray rows=client.select(tableFor(type),"select=*&workspace_id=eq."+wid+"&id=eq."+rid);if(rows.length()==0)return new JSONObject().put("_missing",true).put("id",rid);return rows.getJSONObject(0);\n    }\n\n    public String resolveConflictUseCloud(String workspaceId,String type,long localId,String remoteUuid)throws Exception{\n        JSONObject cloud=cloudConflictSnapshot(workspaceId,type,remoteUuid);if(cloud.optBoolean("_missing",false)){db.discardPendingEntitySync(type,localId);db.forceApplyRemoteDeletion(type,localId,remoteUuid);return "Cloud record no longer exists · local copy removed";}\n        db.discardPendingEntitySync(type,localId);if(isDeleted(cloud)){db.forceApplyRemoteDeletion(type,localId,remoteUuid);return "Cloud deletion applied";}long saved=db.upsertRemoteEntity(type,cloud);if(saved<=0)throw new Exception("Cloud version could not be applied because a related record is not available yet");db.resolveSyncConflict(type,localId);return "Cloud version applied";\n    }\n\n'''
