new_sync=r'''    private String syncTypeLabel(String type){
        if("customer".equals(type))return "Customer";if("site".equals(type))return "Site";if("customer_site".equals(type))return "Customer ↔ site";if("asset".equals(type))return "Asset";if("technician".equals(type))return "Technician";if("job".equals(type))return "Job";if("job_photo".equals(type))return "Job photo";if("job_signature".equals(type))return "Job signature";if("maintenance_log".equals(type))return "Maintenance";return type;
    }

    private String localConflictSummary(String type,long id){
        AppDatabase.Row r=db.syncEntity(type,id);if(r.id()==0)return db.syncEntityLabel(type,id);
        if("job".equals(type))return r.s("report_no")+" · "+r.s("title")+"\nStatus: "+r.s("status")+" · Date: "+r.s("job_date")+"\nTechnician: "+(r.s("technician").isEmpty()?"Unassigned":r.s("technician"));
        if("customer".equals(type))return r.s("name")+(r.s("contact").isEmpty()?"":"\nContact: "+r.s("contact"))+(r.s("phone").isEmpty()?"":" · "+r.s("phone"));
        if("site".equals(type))return r.s("name")+(r.s("address").isEmpty()?"":"\n"+r.s("address"));
        if("asset".equals(type))return (r.s("tag").isEmpty()?"":r.s("tag")+" · ")+r.s("name")+(r.s("serial").isEmpty()?"":"\nSerial: "+r.s("serial"));
        if("technician".equals(type))return r.s("name")+(r.s("role").isEmpty()?"":" · "+r.s("role"));
        return db.syncEntityLabel(type,id);
    }

    private String cloudConflictSummary(String type,JSONObject o){
        if(o==null||o.optBoolean("_missing",false))return "Cloud record is no longer available.";boolean deleted=!o.isNull("deleted_at")&&!o.optString("deleted_at","").isEmpty();String stamp=o.optString("updated_at","");String text;
        if("job".equals(type))text=o.optString("report_no","")+" · "+o.optString("title","")+"\nStatus: "+o.optString("status","")+" · Date: "+o.optString("job_date","");
        else if("customer".equals(type))text=o.optString("name","")+(o.optString("contact","").isEmpty()?"":"\nContact: "+o.optString("contact",""));
        else if("site".equals(type))text=o.optString("name","")+(o.optString("address","").isEmpty()?"":"\n"+o.optString("address",""));
        else if("asset".equals(type))text=(o.optString("tag","").isEmpty()?"":o.optString("tag","")+" · ")+o.optString("name","")+(o.optString("serial","").isEmpty()?"":"\nSerial: "+o.optString("serial",""));
        else if("technician".equals(type))text=o.optString("name","")+(o.optString("role","").isEmpty()?"":" · "+o.optString("role",""));
        else text=syncTypeLabel(type);
        if(!stamp.isEmpty())text+="\nCloud updated: "+stamp;if(deleted)text+="\nCloud state: Deleted";return text;
    }

    private void showSyncConflict(AppDatabase.Row conflict){
        String type=conflict.s("entity_type"),remote=conflict.s("remote_uuid");long id=parse(conflict.s("entity_id"));if(id<=0){toast("Conflict record is invalid");return;}
        runCloud("Loading conflict details…",()->cloudSync.cloudConflictSnapshot(accountTeam.workspaceId(),type,remote),obj->showSyncConflictComparison(conflict,(JSONObject)obj));
    }

    private void showSyncConflictComparison(AppDatabase.Row conflict,JSONObject cloud){
        String type=conflict.s("entity_type"),remote=conflict.s("remote_uuid");long id=parse(conflict.s("entity_id"));String label=db.syncEntityLabel(type,id);String changed=conflict.s("local_changed_at"),detected=conflict.s("detected_at");
        String message="LOCAL · unsynced"+(changed.isEmpty()?"":" · "+changed)+"\n"+localConflictSummary(type,id)+"\n\nCLOUD"+"\n"+cloudConflictSummary(type,cloud)+"\n\nWhy protected\n"+conflict.s("reason")+(detected.isEmpty()?"":"\nDetected: "+detected);
        MaterialAlertDialogBuilder d=new MaterialAlertDialogBuilder(this).setTitle(label).setMessage(message).setNegativeButton("Review later",null);
        d.setPositiveButton("Keep this device",(x,w)->new MaterialAlertDialogBuilder(this).setTitle("Keep this device's version?").setMessage("Fida Field will push this device's unsynced version to the workspace. Other pending changes on this device will also be synchronized.").setNegativeButton("Cancel",null).setPositiveButton("Keep & sync",(a,b)->runCloud("Synchronizing this device…",()->cloudSync.syncNow(accountTeam.workspaceId(),accountTeam.canManageTeam()),obj->{CloudSyncFoundation.SyncResult r=(CloudSyncFoundation.SyncResult)obj;toast(r.message);showCloudSync();})).show());
        d.setNeutralButton("Use cloud version",(x,w)->new MaterialAlertDialogBuilder(this).setTitle("Use the cloud version?").setMessage("This discards this device's unsynced changes for "+label+". If the cloud record was deleted, the local record and local dependent changes may also be removed. This cannot be undone from Sync Diagnostics.").setNegativeButton("Cancel",null).setPositiveButton("Use cloud",(a,b)->runCloud("Applying cloud version…",()->cloudSync.resolveConflictUseCloud(accountTeam.workspaceId(),type,id,remote),obj->{toast(String.valueOf(obj));showCloudSync();})).show());
        d.show();
    }

    private void showCloudSync(){
        CloudSyncWorker.configure(this,prefs.getBoolean(CloudSyncWorker.KEY_ENABLED,true));
        setHeader("Cloud & Team Sync","Sync status, diagnostics & conflict protection");clear();LinearLayout b=body(page());MaterialButton back=outlineButton("← Back");back.setOnClickListener(v->showMore());b.addView(back);
        b.addView(section("Workspace"));b.addView(info("Workspace",accountTeam.hasWorkspace()?accountTeam.workspaceName():"Not set up"));b.addView(info("Role",accountTeam.accountRole().isEmpty()?"Local user":accountTeam.accountRole()));b.addView(info("Cloud binding",accountTeam.hasCloudWorkspace()?"Bound":"Local only"));b.addView(info("Workspace access",workspaceAccessRevoked()?"Disabled":cloudSync.workspaceAccessState()));b.addView(info("Access checked",cloudSync.workspaceAccessCheckedAt()));
        b.addView(section("Sync health"));b.addView(info("Status",cloudSync.backendStatus()));b.addView(info("Account",cloudSync.accountEmail().isEmpty()?"Not signed in":cloudSync.accountEmail()));b.addView(info("Last sync",cloudSync.lastSync()));b.addView(info("Last result",cloudSync.lastResult()));long pending=cloudSync.pendingChanges(),conflicts=cloudSync.conflictCount();b.addView(info("Pending changes",String.valueOf(pending)));b.addView(info("Protected conflicts",String.valueOf(conflicts)));b.addView(info("Last background sync",prefs.getString(CloudSyncWorker.KEY_LAST_RUN,"Never")));
        if(conflicts>0)b.addView(empty(conflicts+" conflict"+(conflicts==1?" is":"s are")+" protected. Nothing is overwritten automatically. Open a conflict below to compare this device with the cloud and choose which version to keep."));else if(pending>0)b.addView(paragraph("This device has changes waiting to reach the workspace. Use Sync now when you have a connection."));else if(cloudSync.signedIn()&&accountTeam.hasCloudWorkspace())b.addView(paragraph("This device is currently clear: no pending business changes or protected conflicts."));
        MaterialSwitch autoSync=new MaterialSwitch(this);autoSync.setText("Automatic cloud sync");autoSync.setChecked(prefs.getBoolean(CloudSyncWorker.KEY_ENABLED,true));autoSync.setOnCheckedChangeListener((button,checked)->{prefs.edit().putBoolean(CloudSyncWorker.KEY_ENABLED,checked).apply();CloudSyncWorker.configure(this,checked);toast(checked?"Automatic sync enabled":"Automatic sync disabled");});b.addView(autoSync);
        MaterialButton sync=button(conflicts>0?"Sync safe changes now":"Sync now");sync.setEnabled(cloudSync.backendConfigured()&&cloudSync.signedIn()&&accountTeam.hasCloudWorkspace()&&!workspaceAccessRevoked());sync.setOnClickListener(v->runCloud("Synchronizing workspace…",()->cloudSync.syncNow(accountTeam.workspaceId(),accountTeam.canManageTeam()),obj->{CloudSyncFoundation.SyncResult r=(CloudSyncFoundation.SyncResult)obj;refreshEntitlementsAndBranding();toast(r.message);showCloudSync();}));b.addView(sync);
        if(cloudSync.signedIn()&&accountTeam.hasCloudWorkspace()){MaterialButton accessCheck=outlineButton("Check workspace access");accessCheck.setOnClickListener(v->runCloud("Checking workspace access…",()->cloudSync.refreshWorkspaceAccess(accountTeam.workspaceId()),obj->{CloudSyncFoundation.WorkspaceMembership wm=(CloudSyncFoundation.WorkspaceMembership)obj;if(wm==null){toast("Workspace access is disabled");showWorkspaceAccessBlocked();}else{accountTeam.bindCloudWorkspace(wm.id,wm.name,wm.role);toast("Access active · "+wm.role);showCloudSync();}}));b.addView(accessCheck);}else{b.addView(paragraph("Sign in and bind a cloud workspace under Account & Workspace before synchronization can run."));MaterialButton account=outlineButton("Open Account & Workspace");account.setOnClickListener(v->showAccountWorkspace());b.addView(account);}

        b.addView(section("Pending on this device"));List<AppDatabase.Row> pendingRows=db.pendingSyncDiagnosticRows(20);if(pendingRows.isEmpty())b.addView(empty("No pending changes."));else{for(AppDatabase.Row q:pendingRows){String type=q.s("entity_type");long id=parse(q.s("entity_id"));String state="delete".equals(q.s("operation"))?"Delete pending":"Upload pending";MaterialCardView c=rowCard(db.syncEntityLabel(type,id),syncTypeLabel(type)+(q.s("changed_at").isEmpty()?"":" · changed "+q.s("changed_at")),state);c.setClickable(false);c.setFocusable(false);b.addView(c);}if(pending>pendingRows.size())b.addView(paragraph("Showing the most recent "+pendingRows.size()+" of "+pending+" pending changes. Photos, signatures and maintenance items are synchronized automatically with their related job/asset."));}

        b.addView(section("Protected conflicts"));List<AppDatabase.Row> conflictRows=db.recentSyncConflicts(20);if(conflictRows.isEmpty())b.addView(empty("No protected conflicts."));else for(AppDatabase.Row c:conflictRows){String type=c.s("entity_type");long id=parse(c.s("entity_id"));MaterialCardView card=rowCard(db.syncEntityLabel(type,id),syncTypeLabel(type)+" · "+c.s("reason"),"Review");card.setOnClickListener(v->showSyncConflict(c));b.addView(card);}
        b.addView(paragraph("Conflict protection prevents a cloud change from silently replacing unsynced work on this device. ‘Keep this device’ pushes your local version; ‘Use cloud version’ intentionally discards the pending local version for that record."));

        b.addView(section("This device"));b.addView(info("Device ID",cloudSync.deviceId()));MaterialButton copy=outlineButton("Copy device ID");copy.setOnClickListener(v->{android.content.ClipboardManager cm=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);cm.setPrimaryClip(android.content.ClipData.newPlainText("Fida Field device ID",cloudSync.deviceId()));toast("Device ID copied");});b.addView(copy);
        if(cloudSync.signedIn()&&accountTeam.hasCloudWorkspace()){MaterialButton team=outlineButton("Refresh team only");team.setOnClickListener(v->runCloud("Refreshing team…",()->{cloudSync.refreshTeamCache(accountTeam.workspaceId(),accountTeam.canManageTeam());return null;},obj->{toast("Team refreshed");showCloudSync();}));b.addView(team);}
    }

'''
replace_between(MAIN,'    private void showCloudSync(){','    private void showUpgradeRequired(String feature){',new_sync)

